const { chromium } = require('/tmp/opencode/pw/node_modules/playwright');
(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage({ viewport: { width: 1280, height: 720 }, deviceScaleFactor: 1 });
  const consoleErrors = [];
  page.on('pageerror', e => consoleErrors.push('PAGEERROR:' + e.message));
  page.on('console', msg => { if (msg.type() === 'error') consoleErrors.push('CONSOLE:' + msg.text()); });
  await page.goto('http://127.0.0.1:8000/index.html', { waitUntil: 'networkidle' });
  await page.locator('#start-career').click();
  await page.waitForTimeout(800);
  const desktop = await page.evaluate(() => {
    const el = document.querySelector('.game-screen');
    const cs = getComputedStyle(el);
    return { h: el.getBoundingClientRect().height, css: cs.height, display: cs.display };
  });
  console.log('DESKTOP', desktop);
  const mobile = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2 });
  mobile.on('pageerror', e => consoleErrors.push('M_PAGEERROR:' + e.message));
  mobile.on('console', msg => { if (msg.type() === 'error') consoleErrors.push('M_CONSOLE:' + msg.text()); });
  await mobile.goto('http://127.0.0.1:8000/index.html', { waitUntil: 'networkidle' });
  await mobile.locator('#start-career').click();
  await mobile.waitForTimeout(800);
  const mobileInfo = await mobile.evaluate(() => {
    const el = document.querySelector('.game-screen');
    const cs = getComputedStyle(el);
    return { h: el.getBoundingClientRect().height, css: cs.height, display: cs.display };
  });
  console.log('MOBILE', mobileInfo);
  console.log('ERRORS', consoleErrors.length ? consoleErrors : 'NONE');
  await browser.close();
})();
NODE

